class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        boolean[] ok = new boolean[26];
        for (char c : allowed.toCharArray()) ok[c - 'a'] = true;
        int count = 0;
        for (String w : words) {
            boolean consistent = true;
            for (char c : w.toCharArray()) {
                if (!ok[c - 'a']) { consistent = false; break; }
            }
            if (consistent) count++;
        }
        return count;
    }
}

class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        int allowedMask = 0;
        for (char c : allowed.toCharArray()) allowedMask |= (1 << (c - 'a'));
        int count = 0;
        for (String w : words) {
            int wordMask = 0;
            for (char c : w.toCharArray()) wordMask |= (1 << (c - 'a'));
            if ((wordMask & ~allowedMask) == 0) count++;
        }
        return count;
    }
}
